diff --git a/lib/src/js/async_job_pool.dart b/lib/src/js/async_job_pool.dart
index 65cb07b..cd4243f 100644
--- a/lib/src/js/async_job_pool.dart
+++ b/lib/src/js/async_job_pool.dart
@@ -35,6 +35,8 @@
 /// an error envelope).
 library;

+import 'dart:io';
+
 import 'package:quickjs_runtime/quickjs_runtime.dart';

 import '../config/property_reader.dart';
@@ -90,11 +92,17 @@ Map<String, dynamic> _runJobOnWorker(int workerId, AsyncJobRequest request) {
       fnSource: request.fnSource,
       argsJson: request.argsJson,
     );
-    // dispatched fns can register timers; drain them once the job settles
+    // dispatched fns can register timers; drain them once the job settles.
+    // DRAIN-ERROR POLICY (epam/dmtools-dart#243): a worker swallows a drain
+    // failure — with a log line — because the dispatched function's own
+    // result/error IS the job and must not be masked by a late timer
+    // callback. The MAIN engine deliberately propagates instead (see
+    // JsJobRunner): there the timer chain is part of the run's contract.
     try {
       compat?.drainTimers();
-    } catch (_) {
-      // a timer drain failure must not mask the job's own result/error
+    } catch (e) {
+      stderr.writeln('[jsr:$workerId] timer drain failed (envelope '
+          'unchanged): $e');
     }
     return result;
   } catch (e) {
diff --git a/lib/src/js/job_runner.dart b/lib/src/js/job_runner.dart
index d2ef078..e743eae 100644
--- a/lib/src/js/job_runner.dart
+++ b/lib/src/js/job_runner.dart
@@ -134,6 +134,12 @@ class JsJobRunner {
       final result = _callAction(rt);
       // nodeCompat scripts may register timers (setTimeout-as-sleep etc.);
       // block-mode drain (dmtools default) settles them like Node would.
+      // DRAIN-ERROR POLICY (epam/dmtools-dart#243): the MAIN engine
+      // deliberately propagates a drain failure — for a script the timer
+      // chain IS part of the run's contract (side-effect timers, sleep
+      // pattern), and silently dropping callbacks would report success
+      // with lost effects. Worker dispatches swallow-with-a-log instead
+      // (async_job_pool.dart): there the fn's return value is the job.
       compat?.drainTimers();
       return result;
     } finally {
diff --git a/test/js/async_job_pool_test.dart b/test/js/async_job_pool_test.dart
index 6f47581..56b7a96 100644
--- a/test/js/async_job_pool_test.dart
+++ b/test/js/async_job_pool_test.dart
@@ -29,6 +29,7 @@ void main() {
   _registerWorkerModuleTests(fixture);
   _registerPoolDispatchTests(fixture);
   _registerPoolErrorTests(fixture);
+  _registerDrainPolicyTests(fixture);
 }

 /// Shared fixtures for one test run (temp dir + booted worker pool).
@@ -333,3 +334,46 @@ void _registerPoolErrorTests(_Fixture f) {
     );
   });
 }
+
+/// Timer-drain error policy (epam/dmtools-dart#243): the MAIN engine
+/// propagates a drain failure — the script's timer chain is part of the
+/// run's contract (side-effect timers, setTimeout-as-sleep). A WORKER
+/// swallows it with a log line: the dispatched fn's own result/error IS
+/// the job and must not be masked by a late timer callback.
+void _registerDrainPolicyTests(_Fixture f) {
+  test('main engine: a throwing timer callback fails the whole run', () {
+    expect(
+      () => f.runScript(
+        '''
+function action(params) {
+  setTimeout(function () { throw new Error('drain-boom'); }, 0);
+  return 'ok';
+}
+''',
+        jobParams: const {'nodeCompat': true, 'parallelWorkers': 2},
+      ),
+      throwsA(predicate(
+        (e) => e.toString().contains('drain-boom'),
+        'error mentioning drain-boom',
+      )),
+    );
+  });
+
+  test('worker: a throwing late timer does not mask the fn result', () {
+    final result = f.runScript(
+      '''
+function action(params) {
+  return runAsync(
+    function () {
+      setTimeout(function () { throw new Error('late-boom'); }, 0);
+      return 42;
+    },
+    null
+  ).wait();
+}
+''',
+      jobParams: const {'nodeCompat': true, 'parallelWorkers': 2},
+    );
+    expect(result, '42');
+  });
+}

