/// Runs JavaScript jobs in a QuickJS runtime with full tool bridge support.
///
/// Phase 4 orchestrator — mirrors the Java `JobJavaScriptBridge` /
/// `JavaScriptExecutor` pipeline:
/// 1. Create a QuickJS runtime.
/// 2. Inject job context (`params.jobParams`, `params.ticket`, …).
/// 3. Install the CommonJS `require` loader ([installRequireLoader]).
/// 4. Generate and eval snake_case tool wrapper JS for every tool.
/// 5. Register host functions (`executeToolViaJava`, `file_read`,
///    `set_env_variable`, `console`) via [ToolBridge] — last, so the direct
///    `file_read` global wins over the generated wrapper.
/// 6. Set the current script directory (relative `require` base), load the
///    script source (file / inline / URL — Java `loadJavaScriptCode`
///    parity), and eval it.
/// 7. Call the script's `action(params)` — the JSRunner contract. Scripts
///    without an `action` function fail with the Java-parity error
///    `JavaScript code must define an 'action' function`.
library;

import 'dart:convert';
import 'dart:io';

import '../mcp/default_tool_registry.dart';
import '../mcp/tool_registry.dart';
import 'package:quickjs_runtime/quickjs_runtime.dart';
import 'async_job_pool.dart';
import 'engine_factory.dart';
import 'sync_http_client.dart';

/// Optional configuration for [JsJobRunner.runScript].
///
/// Bundles the less-commonly-used parameters so that [JsJobRunner.runScript]
/// stays within the quality-gate param limit.
class JsRunConfig {
  /// Creates a run configuration.
  const JsRunConfig({
    this.integrationFilter,
    this.registry,
    this.extraGlobals,
    this.contextParams,
    this.pool,
    this.httpFetch,
  });

  /// Restricts generated wrappers to the named integrations.
  ///
  /// When null, wrappers for all integrations are generated.
  final Set<String>? integrationFilter;

  /// Tool registry to use; defaults to the full catalog when null.
  final ToolRegistry? registry;

  /// Additional top-level JS globals set after `params` but before the
  /// script runs.
  final Map<String, dynamic>? extraGlobals;

  /// Additional entries merged into the `params` object passed to
  /// `action(params)` — mirrors Java `JavaScriptExecutor.withJobContext()` /
  /// `.with()` bindings (`response`, `initiator`, `inputJql`, `metadata`, …).
  ///
  /// Null-valued entries must be omitted by the caller (Java's
  /// `JSONObject.put(key, null)` removes the key).
  final Map<String, dynamic>? contextParams;

  /// Worker pool for `runAsync(fn, args)` (defaults to
  /// [AsyncJobPool.instance]). Only consulted when `jobParams` carries
  /// `parallelWorkers >= 2`; tests boot a private pool and pass it here.
  final AsyncJobPool? pool;

  /// Alternate `fetch` transport for the node/js compat layer on the
  /// main engine (JSON in, JSON out). Defaults to the pooled
  /// [SyncHttpClient]; see [EngineSpec.httpFetch].
  final String? Function(String requestJson)? httpFetch;
}

/// A resolved script source: the [code] plus the [filename] used for eval
/// diagnostics.
class _LoadedScript {
  const _LoadedScript(this.code, this.filename);

  /// Inline code: the source itself is the "path", so eval diagnostics
  /// get a stable pseudo-filename.
  const _LoadedScript.inline(String code) : this(code, '<inline>');

  final String code;
  final String filename;
}

/// Runs JavaScript agent/test scripts in a QuickJS runtime.
class JsJobRunner {
  /// Creates a new job runner.
  const JsJobRunner();

  /// Runs [scriptPath] as a JS job with the given [jobParams].
  ///
  /// Mirrors the Java `JobJavaScriptBridge.executeJavaScript` contract:
  /// the script source is resolved via `loadJavaScriptCode` parity (file,
  /// inline code, or http(s) URL), evaluated, and its `action(params)`
  /// function is invoked — scripts without `action` fail with the
  /// Java-parity error. The action's return value (JSON) is the result;
  /// `null` means JS `undefined`.
  ///
  /// - [jobParams] — injected as `params.jobParams` in the JS global scope.
  /// - [ticket] — injected as `params.ticket` when non-null.
  /// - [workingDirectory] — base for relative file paths in tool calls.
  /// - [config] — optional [JsRunConfig] for integration filtering, custom
  ///   registries, and extra JS globals / params context.
  String? runScript({
    required String scriptPath,
    required Map<String, dynamic> jobParams,
    Map<String, dynamic>? ticket,
    String? workingDirectory,
    JsRunConfig? config,
  }) {
    final cfg = config ?? const JsRunConfig();
    final rt = QuickjsRuntime();
    try {
      final reg = cfg.registry ?? createDefaultToolRegistry();
      final compat =
          _wireRuntime(rt, reg, jobParams, ticket, workingDirectory, cfg);
      if (_parallelWorkers(jobParams) >= 2) {
        _wireAsyncPool(
          rt,
          scriptPath: scriptPath,
          jobParams: jobParams,
          ticket: ticket,
          workingDirectory: workingDirectory,
          cfg: cfg,
        );
      }
      setScriptDirectory(rt, scriptPath);
      final loaded = _loadJavaScriptCode(scriptPath);
      _evalScript(rt, loaded.code, loaded.filename);
      final result = _callAction(rt);
      // nodeCompat scripts may register timers (setTimeout-as-sleep etc.);
      // block-mode drain (dmtools default) settles them like Node would.
      // DRAIN-ERROR POLICY (epam/dmtools-dart#243): the MAIN engine
      // deliberately propagates a drain failure — for a script the timer
      // chain IS part of the run's contract (side-effect timers, sleep
      // pattern), and silently dropping callbacks would report success
      // with lost effects. Worker dispatches swallow-with-a-log instead
      // (async_job_pool.dart): there the fn's return value is the job.
      compat?.drainTimers();
      return result;
    } finally {
      rt.close();
    }
  }

  /// Effective `parallelWorkers` knob (0 when absent or non-numeric).
  ///
  /// Values >= 2 wire the `runAsync` API onto the engine; everything else
  /// keeps the default sequential surface (default-off, zero deviation).
  int _parallelWorkers(Map<String, dynamic> jobParams) {
    final value = jobParams['parallelWorkers'];
    return value is num ? value.toInt() : 0;
  }

  /// Wires the `runAsync` / `AsyncJob` surface onto [rt] by delegating
  /// to [AsyncJobPool.attachMainRuntime] (quickjs_runtime owns the
  /// `__jsr*` host functions and the prelude — no adapter duplicate,
  /// epam/dmtools-dart#242).
  ///
  /// Uses [JsRunConfig.pool], defaulting to [AsyncJobPool.instance]. When
  /// the pool is not booted, `runAsync(...)` throws a clear JS error on
  /// first use (dispatch sentinel) instead of failing the engine wiring.
  void _wireAsyncPool(
    QuickjsRuntime rt, {
    required String scriptPath,
    required Map<String, dynamic> jobParams,
    required Map<String, dynamic>? ticket,
    required String? workingDirectory,
    required JsRunConfig cfg,
  }) {
    final pool = cfg.pool ?? AsyncJobPool.instance;
    final params = buildParamsMap(
      jobParams: jobParams,
      ticket: ticket,
      contextParams: cfg.contextParams,
      extraGlobals: cfg.extraGlobals,
    );
    pool.attachMainRuntime(
      rt,
      scriptDirectory: jsDirectoryOf(scriptPath),
      workingDirectory: workingDirectory,
      params: params,
    );
  }

  /// Evaluates the script source, surfacing JS exceptions.
  ///
  /// QuickJS reports eval exceptions through `errMsg` (the eval itself
  /// returns `null`); Java wraps the same failure in
  /// `RuntimeException("JavaScript execution failed: …")` — mirrored here.
  void _evalScript(QuickjsRuntime rt, String code, String filename) {
    final errors = <String?>[];
    rt.eval(code, filename: filename, errMsg: errors);
    if (errors.isNotEmpty) {
      throw StateError('JavaScript execution failed: ${errors.first}');
    }
  }

  /// Invokes the script's `action(params)` (JSRunner contract).
  ///
  /// Missing / non-function `action` fails with the Java-parity message;
  /// exceptions raised inside `action` surface as evaluation failures.
  String? _callAction(QuickjsRuntime rt) {
    final kind = rt.eval('typeof action', filename: '<action_check>');
    if (jsonDecode(kind ?? '"undefined"') != 'function') {
      throw StateError("JavaScript code must define an 'action' function");
    }
    final errors = <String?>[];
    final result = rt.eval(
      'action(params)',
      filename: '<action_call>',
      errMsg: errors,
    );
    if (errors.isNotEmpty) {
      throw StateError('JavaScript execution failed: ${errors.first}');
    }
    return result;
  }

  /// Wires up job context, require loader, tool wrappers, and host
  /// functions on [rt].
  ///
  /// Delegates to [wireEngine] — the shared wiring used verbatim by the
  /// `runAsync` worker engines, so both paths stay behaviorally identical.
  /// Host functions are registered **after** the generated tool wrappers so
  /// that the direct `file_read` global (returning the raw content string,
  /// as testRunner.js requires) takes precedence over the wrapper that
  /// dispatches through `executeToolViaJava` with an `{content: …}` shape.
  NodeCompatHandle? _wireRuntime(
    QuickjsRuntime rt,
    ToolRegistry registry,
    Map<String, dynamic> jobParams,
    Map<String, dynamic>? ticket,
    String? workingDirectory,
    JsRunConfig config,
  ) {
    return wireEngine(
      rt,
      EngineSpec(
        context: EngineContext(
          jobParams: jobParams,
          ticket: ticket,
          contextParams: config.contextParams,
          extraGlobals: config.extraGlobals,
        ),
        registry: registry,
        integrationFilter: config.integrationFilter,
        workingDirectory: workingDirectory,
        httpFetch: config.httpFetch,
      ),
    );
  }

  // ── Script source resolution (Java loadJavaScriptCode parity) ─────────

  /// Resolves [jsSourceOrPath] to script code — Java
  /// `JobJavaScriptBridge.loadJavaScriptCode` parity:
  /// http(s) URLs fetch remotely; inline code (starts with `function` or
  /// contains `action`) and strings without `/` / `.js` pass through
  /// as-is; everything else loads from the filesystem.
  _LoadedScript _loadJavaScriptCode(String jsSourceOrPath) {
    if (jsSourceOrPath.startsWith('http://') ||
        jsSourceOrPath.startsWith('https://')) {
      return _LoadedScript(
        _loadFromUrl(jsSourceOrPath),
        jsSourceOrPath,
      );
    }
    final isInline = jsSourceOrPath.trim().startsWith('function') ||
        jsSourceOrPath.contains('action') ||
        (!jsSourceOrPath.contains('/') && !jsSourceOrPath.endsWith('.js'));
    if (isInline) return _LoadedScript.inline(jsSourceOrPath);
    return _LoadedScript(_loadFromFile(jsSourceOrPath), jsSourceOrPath);
  }

  /// Loads script code from the filesystem, or fails with the Java-parity
  /// `JavaScript file not found` message.
  String _loadFromFile(String path) {
    try {
      return File(path).readAsStringSync();
    } on FileSystemException {
      throw StateError(
        'JavaScript file not found in resources or filesystem: $path',
      );
    }
  }

  /// Synchronously fetches [url] via [SyncHttpClient] (curl subprocess).
  String _loadFromUrl(String url) {
    final response = SyncHttpClient.get(url);
    if (!response.isOk) {
      throw StateError(
        'Failed to load JS from source code: $url '
        '(HTTP ${response.statusCode}: ${response.body})',
      );
    }
    return response.body;
  }
}

import 'dart:convert';
import 'dart:io';

import 'package:dmtools/src/js/async_job_pool.dart';
import 'package:dmtools/src/js/job_runner.dart';
import 'package:test/test.dart';

/// Tests for the `runAsync(fn, args)` engine-worker pool
/// (epam/dmtools-dart#224): dispatch/wait mechanics, error propagation,
/// worker-engine parity (params, require, host tools), the
/// `parallelWorkers` knob, and the pool lifecycle.
///
/// Every script defines `action(params)` — the JSRunner contract enforced
/// by [JsJobRunner.runScript].
void main() {
  final fixture = _Fixture();

  setUp(() async {
    fixture.newRun();
    await fixture.pool.boot();
  });

  tearDown(fixture.disposeRun);

  _registerJobApiCoreTests(fixture);
  _registerJobApiKnobTests(fixture);
  _registerWorkerParityTests(fixture);
  _registerWorkerToolTests(fixture);
  _registerWorkerModuleTests(fixture);
  _registerPoolDispatchTests(fixture);
  _registerPoolErrorTests(fixture);
  _registerDrainPolicyTests(fixture);
}

/// Shared fixtures for one test run (temp dir + booted worker pool).
class _Fixture {
  Directory? _tmp;
  AsyncJobPool? _pool;

  AsyncJobPool get pool => _pool!;
  Directory get tmp => _tmp!;

  /// Creates a fresh temp dir and a fresh (unbooted) 2-worker pool.
  void newRun() {
    _tmp = Directory.systemTemp.createTempSync('dmtools_async');
    _pool = AsyncJobPool(workers: 2);
  }

  void disposeRun() {
    _pool?.dispose();
    _tmp?.deleteSync(recursive: true);
  }

  String writeScript(String source) {
    final script = File('${tmp.path}/main.js')..writeAsStringSync(source);
    return script.path;
  }

  /// Runs [source] with the test pool enabled (`parallelWorkers: 2`).
  String? runScript(
    String source, {
    Map<String, dynamic>? jobParams,
    JsRunConfig? config,
  }) {
    return const JsJobRunner().runScript(
      scriptPath: writeScript(source),
      jobParams: jobParams ?? const {'parallelWorkers': 2},
      config: config ?? JsRunConfig(pool: pool),
    );
  }
}

/// `runAsync` / `AsyncJob` / `runAsync.all` API surface basics.
void _registerJobApiCoreTests(_Fixture f) {
  test('runAsync returns a job whose wait() yields the function result', () {
    final result = f.runScript('''
function action(params) {
    var job = runAsync(function(args) { return { sum: args.a + args.b }; },
        { a: 2, b: 3 });
    return { r: job.wait() };
}
''');
    expect(jsonDecode(result!), {
      'r': {'sum': 5}
    });
  });

  test('runAsync.all waits every job and returns ordered results', () {
    final result = f.runScript('''
function action(params) {
    var fn = function(args) { return args.n * 10; };
    return runAsync.all([
        runAsync(fn, { n: 1 }),
        runAsync(fn, { n: 2 }),
        runAsync(fn, { n: 3 })
    ]).wait();
}
''');
    expect(jsonDecode(result!), [10, 20, 30]);
  });

  test('runAsync validates its arguments', () {
    final result = f.runScript('''
function action(params) {
    try { runAsync(42, null); return 'no-error'; } catch (e) {
        return String(e);
    }
}
''');
    expect(result, contains('runAsync expects a function'));
  });
}

/// Knob and wiring-fallback behavior for the `runAsync` surface.
void _registerJobApiKnobTests(_Fixture f) {
  test('parallelWorkers knob off keeps the default sequential surface', () {
    final result = f.runScript(
      'function action(params) { return typeof runAsync; }',
      jobParams: const {},
    );
    expect(result, '"undefined"');
  });

  test('runAsync on an unbooted pool surfaces a clear JS error', () {
    final result = f.runScript(
      '''
function action(params) {
    try {
        runAsync(function() { return 1; }, null);
        return 'no-error';
    } catch (e) {
        return String(e);
    }
}
''',
      config: JsRunConfig(pool: AsyncJobPool(workers: 1)),
    );
    expect(result, contains('not booted'));
  });

  test('runScript action-error handling is untouched by the async wiring', () {
    expect(
      () => f.runScript('function action(params) { throw new Error('
          "'action-failed'); }"),
      throwsA(isA<StateError>().having(
        (e) => e.message,
        'message',
        contains('action-failed'),
      )),
    );
  });
}

/// Worker-engine parallelism and error propagation.
void _registerWorkerParityTests(_Fixture f) {
  test('two jobs run in parallel (wall time ~ one job, not the sum)', () {
    final result = f.runScript('''
function action(params) {
    var started = Date.now();
    var fn = function(args) {
        var end = Date.now() + args.ms;
        while (Date.now() < end) { /* busy wait */ }
        return args.ms;
    };
    var total = runAsync.all([
        runAsync(fn, { ms: 400 }),
        runAsync(fn, { ms: 400 })
    ]).wait();
    return { elapsed: Date.now() - started, total: total };
}
''');
    final decoded = jsonDecode(result!) as Map<String, dynamic>;
    final elapsed = decoded['elapsed'] as int;
    // Sequential execution would need >= 800ms of busy wait alone.
    expect(elapsed, lessThan(780), reason: 'jobs must overlap: $decoded');
    expect(decoded['total'], [400, 400]);
  });

  test('worker JS exceptions propagate through wait()', () {
    final result = f.runScript('''
function action(params) {
    try {
        runAsync(function() { throw new Error('boom-in-worker'); }, null)
            .wait();
        return 'no-error';
    } catch (e) {
        return String(e);
    }
}
''');
    expect(result, contains('boom-in-worker'));
  });
}

/// Worker tool-bridge parity (payloads, params, host functions).
void _registerWorkerToolTests(_Fixture f) {
  test('missing files read via worker tools follow the host contract', () {
    final result = f.runScript('''
function action(params) {
    var job = runAsync(function() {
        var raw = file_read({ path: '/nonexistent/async_target.txt' });
        return raw === null ? 'missing-file-is-null' : 'unexpected';
    }, null);
    return String(job.wait());
}
''');
    // The direct `file_read` host function answers a missing file with JS
    // `null` (same contract as on the main engine) — the worker sees the
    // tool payload verbatim, no special async error channel.
    expect(result, '"missing-file-is-null"');
  });

  test('worker engines see params, wrappers, and the full tool bridge', () {
    final file = File('${f.tmp.path}/tool_target.txt')
      ..writeAsStringSync('worker-tool-ok');
    final result = f.runScript('''
function action(params) {
    return runAsync(function(args) {
        return {
            marker: params.jobParams.marker,
            content: file_read({ path: args.path })
        };
    }, { path: '${file.path}' }).wait();
}
''', jobParams: const {
      'parallelWorkers': 2,
      'marker': 'async-marker',
    });
    expect(jsonDecode(result!), {
      'marker': 'async-marker',
      'content': 'worker-tool-ok',
    });
  });
}

/// Worker module system and console parity.
void _registerWorkerModuleTests(_Fixture f) {
  test('require inside a worker resolves against the script directory', () {
    File('${f.tmp.path}/dep.js').writeAsStringSync('''
module.exports = { double: function(n) { return n * 2; } };
''');
    final result = f.runScript('''
function action(params) {
    var job = runAsync(function(args) {
        var dep = require('./dep.js');
        return dep.double(args.n);
    }, { n: 21 });
    return job.wait();
}
''');
    expect(result, '42');
  });

  test('console output inside workers does not break execution', () {
    final result = f.runScript('''
function action(params) {
    return runAsync(function() {
        console.log('from worker');
        return 'logged';
    }, null).wait();
}
''');
    expect(result, '"logged"');
  });
}

/// Dart-level pool dispatch mechanics (no JS engine on the caller side).
void _registerPoolDispatchTests(_Fixture f) {
  test('dispatch/wait roundtrip without a JS engine on the caller', () {
    final jobId = f.pool.dispatch(
      fnSource: 'function(args) { return args.x + 1; }',
      argsJson: '{"x":41}',
      scriptDirectory: f.tmp.path,
      params: const {},
    );
    final envelope = f.pool.wait(jobId);
    expect(envelope.ok, isTrue);
    expect(envelope.decodedResult, 42);
  });

  test('fire-and-forget jobs are served by a later wait()', () async {
    final jobId = f.pool.dispatch(
      fnSource: 'function(args) { return args; }',
      argsJson: '"late"',
      scriptDirectory: f.tmp.path,
      params: const {},
    );
    await Future<void>.delayed(const Duration(milliseconds: 300));
    expect(f.pool.wait(jobId).decodedResult, 'late');
  });
}

/// Pool error surfaces (unknown/double waits, dead workers).
void _registerPoolErrorTests(_Fixture f) {
  test('unknown and double waits fail with clear errors', () {
    expect(
      () => f.pool.wait(999),
      throwsA(isA<StateError>().having(
        (e) => e.message,
        'message',
        contains('Unknown or already-waited'),
      )),
    );
    final jobId = f.pool.dispatch(
      fnSource: 'function(args) { return 1; }',
      argsJson: 'null',
      scriptDirectory: f.tmp.path,
      params: const {},
    );
    f.pool.wait(jobId);
    expect(() => f.pool.wait(jobId), throwsA(isA<StateError>()));
  });

  test('dead workers surface a clear dispatch error', () async {
    final lone = AsyncJobPool(workers: 1);
    await lone.boot();
    addTearDown(lone.dispose);
    // Kill the idle worker — beforeNextEvent lets it unwind (its private
    // HTTP bridge is disposed by its own finally, so no isolate leaks).
    lone.killWorkerForTest(0);
    await Future<void>.delayed(const Duration(milliseconds: 300));
    expect(
      () => lone.dispatch(
        fnSource: 'function(args) { return 1; }',
        argsJson: 'null',
        scriptDirectory: f.tmp.path,
        params: const {},
      ),
      throwsA(isA<StateError>().having(
        (e) => e.message,
        'message',
        contains('no live workers'),
      )),
    );
  });
}

/// Timer-drain error policy (epam/dmtools-dart#243): the MAIN engine
/// propagates a drain failure — the script's timer chain is part of the
/// run's contract (side-effect timers, setTimeout-as-sleep). A WORKER
/// swallows it with a log line: the dispatched fn's own result/error IS
/// the job and must not be masked by a late timer callback.
void _registerDrainPolicyTests(_Fixture f) {
  test('main engine: a throwing timer callback fails the whole run', () {
    expect(
      () => f.runScript(
        '''
function action(params) {
  setTimeout(function () { throw new Error('drain-boom'); }, 0);
  return 'ok';
}
''',
        jobParams: const {'nodeCompat': true, 'parallelWorkers': 2},
      ),
      throwsA(predicate(
        (e) => e.toString().contains('drain-boom'),
        'error mentioning drain-boom',
      )),
    );
  });

  test('worker: a throwing late timer does not mask the fn result', () {
    final result = f.runScript(
      '''
function action(params) {
  return runAsync(
    function () {
      setTimeout(function () { throw new Error('late-boom'); }, 0);
      return 42;
    },
    null
  ).wait();
}
''',
      jobParams: const {'nodeCompat': true, 'parallelWorkers': 2},
    );
    expect(result, '42');
  });
}

